// SCOUT: reads raw sources, emits candidate problems with evidence
// Dummy stand-in for real ingestion (Slack/tickets/meeting notes)
const candidates = [
  {
    id: 'uc-001',
    title: 'Manual weekly SOC2 evidence collation',
    evidence: [
      { source: 'slack', quote: 'spent 3 hours again copying screenshots into the evidence folder', author: 'user_a' },
      { source: 'ticket', quote: 'evidence collection is the worst part of my week', author: 'user_b' }
    ],
    raisedByCount: 2
  },
  {
    id: 'uc-002',
    title: 'Onboarding checklist manually tracked in a spreadsheet',
    evidence: [
      { source: 'meeting_notes', quote: 'we keep losing track of who finished which onboarding step', author: 'user_c' }
    ],
    raisedByCount: 1
  }
];

return candidates.map(c => ({ json: { useCase: { ...c, stage: 'discovered', log: [{ agent: 'Scout', action: 'candidate_emitted' }] } } }));

// SCORER: scores frequency x time-cost x automatability x blast-radius, ranks, emits shortlist
const items = $input.all().map(i => i.json.useCase);

const scored = items.map(uc => {
  const frequency = uc.raisedByCount;
  const timeCost = 3; // placeholder — replace with your real scoring dimensions
  const automatability = 4;
  const blastRadius = 2; // lower = safer
  const score = (frequency * timeCost * automatability) / blastRadius;
  return { ...uc, score, stage: 'scored', log: [...uc.log, { agent: 'Scorer', action: 'scored', score }] };
});

scored.sort((a, b) => b.score - a.score);

return scored.map(uc => ({ json: { useCase: uc } }));

// Simulates: human picked the top-ranked candidate at Gate 1
const items = $input.all().map(i => i.json.useCase);
const chosen = items[0]; // top of ranked shortlist
chosen.stage = 'chosen';
chosen.log.push({ agent: 'Gate1-Human', action: 'approved_selection', pickedFrom: items.length });
return [{ json: { useCase: chosen } }];

// DEFINER: drafts PRD (problem, users, scope, requirements, success criteria)
const uc = $input.first().json.useCase;

uc.prd = {
  problem: uc.title,
  users: ['placeholder — which internal team/role'],
  scope: 'placeholder — in/out of scope',
  requirements: ['placeholder requirement 1'],
  successCriteria: ['placeholder metric'],
  confidence: 0.7,
  openAssumptions: ['placeholder — anything Definer had to guess']
};
uc.stage = 'defined';
uc.log.push({ agent: 'Definer', action: 'prd_drafted' });

return [{ json: { useCase: uc } }];

const uc = $input.first().json.useCase;
uc.log.push({ agent: 'Gate2-Human', action: 'prd_approved' });
return [{ json: { useCase: uc } }];

// DESIGNER: produces wireframe/mock-up options from approved PRD
const uc = $input.first().json.useCase;

uc.design = {
  variants: ['variant A: dashboard view', 'variant B: form + list view'],
  chosenVariant: null
};
uc.stage = 'designed';
uc.log.push({ agent: 'Designer', action: 'variants_generated' });

return [{ json: { useCase: uc } }];

const uc = $input.first().json.useCase;
uc.design.chosenVariant = uc.design.variants[0];
uc.log.push({ agent: 'Gate3-Human', action: 'design_chosen', chosen: uc.design.chosenVariant });
return [{ json: { useCase: uc } }];

// BUILDER: uses approved PRD + design to build the app on the platform
const uc = $input.first().json.useCase;

uc.build = {
  platformAppId: 'placeholder-app-id',
  status: 'built_not_deployed'
};
uc.stage = 'built';
uc.log.push({ agent: 'Builder', action: 'app_built' });

return [{ json: { useCase: uc } }];

const uc = $input.first().json.useCase;
uc.stage = 'shipped';
uc.log.push({ agent: 'Gate4-Human', action: 'deploy_approved' });
return [{ json: { useCase: uc } }];
